static std::string envelope(const std::string& def, const std::string& in,
                            const char* head = nullptr) {
  std::string s = "{";
  s += head ? head : "\"contractVersion\":1,\"modelId\":\"nl-51-v1\"";
  s += std::string(",\"configurationDigest\":\"") + DIGEST + "\"";
  s += ",\"inputGeneration\":1700000000123,\"serverTime\":\"2026-11-15T10:00:00.123456Z\"";
  if (!def.empty()) s += ",\"definition\":" + def;
  if (!in.empty()) s += ",\"inputs\":" + in;
  return s + "}";
}
static std::string full() { return envelope(DEFINITION, INPUTS); }

static std::string swap(std::string s, const std::string& from, const std::string& to) {
  size_t at = s.find(from);
  if (at == std::string::npos) {
    printf("FIXTURE ERROR: '%s' not found\n", from.c_str());
    exit(2);
  }
  return s.replace(at, from.size(), to);
}

static Envelope meta;
static Definition def;
static Inputs inputs;
static Error parse(const std::string& s) {
  return parseEnvelope(s.c_str(), s.size(), MODEL, meta, def, inputs);
}

static void testValid() {
  CHECK_ERR(Error::Ok, parse(full()));
  CHECK(meta.hasDefinition && meta.hasInputs);
  CHECK(meta.contractVersion == 1);
  CHECK(std::string(meta.modelId) == MODEL);
  CHECK(std::string(meta.digest) == DIGEST);
  CHECK(meta.inputGeneration == 1700000000123LL);
  CHECK(inputs.generation == 1700000000123LL && inputs.bindingCount == 5);
  CHECK(def.brightness == 255 && def.paletteCount == 6 && def.trackCount == 4);
  CHECK(def.segmentCount == 1 + 1 + 3 + 3 && def.gateCount == 2 && def.clockCount == 1);
  CHECK(def.palette[2] == 0x00FF00 && def.palette[4] == 0xFF8000);
  CHECK(def.tracks[2].kind == Kind::Cosine && def.tracks[2].segmentCount == 3);
  CHECK(def.tracks[0].kind == Kind::Constant);
  CHECK(def.clocks[0].periodMs == 5000 && def.gates[0].close == 3500);
  CHECK(inputs.bindings[4].pixel == 51);
  // Omitted definition (digest match) and omitted inputs; null counts as absent; any key order.
  CHECK_ERR(Error::Ok, parse(envelope("", INPUTS)));
  CHECK(!meta.hasDefinition && meta.hasInputs);
  CHECK_ERR(Error::Ok, parse(envelope(DEFINITION, "")));
  CHECK(meta.hasDefinition && !meta.hasInputs);
  CHECK_ERR(Error::Ok, parse(swap(full(), "\"definition\":", "\"inputs2\":null,\"definition\":")));
  CHECK_ERR(Error::Ok, parse(swap(full(), ",\"inputs\":", ",\"definition2\":null,\"inputs\":")));
  std::string nulls = envelope("", "");
  nulls.insert(nulls.size() - 1, ",\"definition\":null,\"inputs\":null");
  CHECK_ERR(Error::Ok, parse(nulls));
  CHECK(!meta.hasDefinition && !meta.hasInputs);
  // Whitespace and unknown (nested) fields are tolerated.
  std::string ws = swap(full(), "\"serverTime\"", "\"extra\":{\"a\":[1,2,{\"b\":null}],\"c\":true},\n  \"serverTime\"");
  CHECK_ERR(Error::Ok, parse("  \n" + ws + " \r\n"));
}

static std::string manyBindings(int n, bool dup = false) {
  std::string s = "{\"generation\":1,\"bindings\":[";
  for (int i = 0; i < n; i++) {
    if (i) s += ",";
    s += "{\"pixel\":" + std::to_string(dup && i == n - 1 ? 0 : i) +
         ",\"trackRef\":0,\"paletteRef\":0}";
  }
  return s + "]}";
}
static std::string manyTracks(int tracks, int segsPerTrack) {
  std::string s =
      "{\"contractVersion\":1,\"modelId\":\"nl-51-v1\",\"palette\":[0],\"tracks\":[";
  for (int i = 0; i < tracks; i++) {
    if (i) s += ",";
    s += "{\"id\":" + std::to_string(i) + ",\"kind\":\"LINEAR\",\"segments\":[";
    for (int j = 0; j < segsPerTrack; j++) {
      if (j) s += ",";
      s += "{\"durationMs\":10,\"from\":0,\"to\":5}";
    }
    s += "]}";
  }
  return s + "],\"gates\":[],\"clocks\":[],\"brightness\":10}";
}

static void testBounds() {
  // Body size.
  std::string big = full();
  big.insert(big.size() - 1, ",\"pad\":\"" + std::string(MAX_BODY_BYTES, 'x') + "\"");
  CHECK_ERR(Error::TooLarge, parse(big));
  std::string exact = full();
  size_t padLen = MAX_BODY_BYTES - exact.size() - 9;  // comma, key, colon, quotes around the padding
  exact.insert(exact.size() - 1, ",\"pad\":\"" + std::string(padLen, 'x') + "\"");
  CHECK(exact.size() == MAX_BODY_BYTES);
  CHECK_ERR(Error::Ok, parse(exact));
  exact.insert(exact.size() - 1, "x");
  CHECK_ERR(Error::TooLarge, parse(exact));
  CHECK_ERR(Error::Malformed, parseEnvelope(nullptr, 0, MODEL, meta, def, inputs));
  CHECK_ERR(Error::Malformed, parse(""));
  CHECK_ERR(Error::Malformed, parseEnvelope(full().c_str(), full().size(), std::string(40, 'm').c_str(), meta, def, inputs));
  {  // embedded NUL inside a string and between tokens
    std::string nul = full();
    nul[nul.find("nl-51") + 2] = '\0';
    CHECK_ERR(Error::Malformed, parse(nul));
    std::string nul2 = full();
    nul2.insert(nul2.size() - 1, std::string(1, '\0'));
    CHECK_ERR(Error::Malformed, parse(nul2));
  }
  // Bindings: 52 fine, 53 rejected, pixel 52 rejected, duplicate rejected.
  CHECK_ERR(Error::Ok, parse(envelope(DEFINITION, manyBindings(52))));
  CHECK(inputs.bindingCount == 52);
  CHECK_ERR(Error::TooManyBindings, parse(envelope(DEFINITION, manyBindings(53))));
  CHECK_ERR(Error::DuplicatePixel, parse(envelope(DEFINITION, manyBindings(5, true))));
  CHECK_ERR(Error::PixelOutOfRange, parse(swap(full(), "\"pixel\":51", "\"pixel\":52")));
  CHECK_ERR(Error::PixelOutOfRange, parse(swap(full(), "\"pixel\":51", "\"pixel\":-1")));
  // Tracks and segments.
  // The 16 KiB body ceiling is reached before 512 segments can be sent (a minimal segment is 32
  // bytes), so the segment ceiling is a defence in depth and only the body bound is observable.
  CHECK_ERR(Error::Ok, parse(envelope(manyTracks(96, 1), "")));
  CHECK(def.trackCount == 96 && def.segmentCount == 96);
  CHECK_ERR(Error::Ok, parse(envelope(manyTracks(1, 400), "")));
  CHECK(def.segmentCount == 400);
  CHECK_ERR(Error::TooManyTracks, parse(envelope(manyTracks(97, 1), "")));
  CHECK_ERR(Error::TooLarge, parse(envelope(manyTracks(1, 513), "")));
  // Palette 256 ok, 257 rejected.
  std::string pal = "0";
  for (int i = 1; i < 256; i++) pal += "," + std::to_string(i);
  CHECK_ERR(Error::Ok, parse(envelope(swap(DEFINITION, "0,255,65280,16776960,16744448,16711680", pal), "")));
  CHECK_ERR(Error::TooManyPalette,
            parse(envelope(swap(DEFINITION, "0,255,65280,16776960,16744448,16711680", pal + ",9"), "")));
  // Gates and clocks (firmware ceilings).
  std::string gates;
  for (int i = 0; i < 97; i++) gates += std::string(i ? "," : "") + "{\"clockRef\":0,\"open\":0,\"close\":1}";
  std::string clocks;
  for (int i = 0; i < 17; i++)
    clocks += std::string(i ? "," : "") + "{\"id\":" + std::to_string(i) + ",\"periodMs\":10,\"offsetMs\":0}";
  CHECK_ERR(Error::TooManyGates, parse(envelope(swap(DEFINITION, "{\"clockRef\":0,\"open\":0,\"close\":3500},{\"clockRef\":0,\"open\":0,\"close\":2000}", gates), "")));
  CHECK_ERR(Error::TooManyClocks, parse(envelope(swap(DEFINITION, "{\"id\":0,\"periodMs\":5000,\"offsetMs\":0}", clocks), "")));
  // Depth: 8 levels allowed in an ignored field, 9 rejected.
  std::string d8 = "[[[[[[[1]]]]]]]";   // depth 7 inside root (depth 1) = 8 total
  std::string d9 = "[[[[[[[[1]]]]]]]]";  // 9 total
  CHECK_ERR(Error::Ok, parse(swap(full(), "\"serverTime\"", "\"x\":" + d8 + ",\"serverTime\"")));
  CHECK_ERR(Error::DepthExceeded, parse(swap(full(), "\"serverTime\"", "\"x\":" + d9 + ",\"serverTime\"")));
  // Self-nesting "cycles" cannot be expressed; absurd nesting is a depth error, not a stack hit.
  std::string deep(5000, '[');
  CHECK_ERR(Error::DepthExceeded, parse(swap(full(), "\"serverTime\"", "\"x\":" + deep + ",\"serverTime\"")));
}

static void testReferences() {
  // Unknown references: gate -> clock, binding -> track and palette (same envelope).
  CHECK_ERR(Error::BadReference, parse(swap(full(), "{\"clockRef\":0,\"open\":0,\"close\":2000}", "{\"clockRef\":1,\"open\":0,\"close\":2000}")));
  CHECK_ERR(Error::BadReference, parse(swap(full(), "\"pixel\":51,\"trackRef\":1", "\"pixel\":51,\"trackRef\":4")));
  CHECK_ERR(Error::BadReference, parse(swap(full(), "\"pixel\":51,\"trackRef\":1,\"paletteRef\":4", "\"pixel\":51,\"trackRef\":1,\"paletteRef\":6")));
  CHECK_ERR(Error::Overflow, parse(swap(full(), "\"trackRef\":1,\"paletteRef\":4", "\"trackRef\":1,\"paletteRef\":300")));
  // Ids must equal their index; kinds must be known.
  CHECK_ERR(Error::BadId, parse(swap(full(), "\"id\":1,\"kind\"", "\"id\":2,\"kind\"")));
  CHECK_ERR(Error::BadId, parse(swap(full(), "{\"id\":0,\"periodMs\"", "{\"id\":3,\"periodMs\"")));
  CHECK_ERR(Error::BadKind, parse(swap(full(), "\"COSINE\"", "\"SPLINE\"")));
  CHECK_ERR(Error::BadKind, parse(swap(full(), "\"COSINE\"", "\"cosine\"")));
  // Constant tracks need exactly one segment.
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"segments\":[{\"durationMs\":1,\"from\":0,\"to\":0}]}", "\"segments\":[{\"durationMs\":1,\"from\":0,\"to\":0},{\"durationMs\":1,\"from\":0,\"to\":0}]}")));
  // Inputs-only: cross-check is deferred to the engine, also available directly.
  CHECK_ERR(Error::Ok, parse(envelope("", swap(INPUTS, "\"trackRef\":3", "\"trackRef\":9"))));
  CHECK_ERR(Error::Ok, parse(full()));
  CHECK_ERR(Error::Ok, validateInputs(def, inputs));
  inputs.bindings[0].trackRef = 4;
  CHECK_ERR(Error::BadReference, validateInputs(def, inputs));
}

static void testVersionModelMalformed() {
  CHECK_ERR(Error::UnsupportedVersion, parse(swap(full(), "\"contractVersion\":1,\"modelId\":\"nl-51-v1\",\"configurationDigest\"", "\"contractVersion\":2,\"modelId\":\"nl-51-v1\",\"configurationDigest\"")));
  CHECK_ERR(Error::UnsupportedVersion, parse(swap(full(), "{\"contractVersion\":1,\"modelId\":\"nl-51-v1\",\"palette\"", "{\"contractVersion\":0,\"modelId\":\"nl-51-v1\",\"palette\"")));
  CHECK_ERR(Error::ModelMismatch, parse(swap(full(), "\"modelId\":\"nl-51-v1\",\"configurationDigest\"", "\"modelId\":\"other\",\"configurationDigest\"")));
  CHECK_ERR(Error::ModelMismatch, parse(swap(full(), "\"modelId\":\"nl-51-v1\",\"palette\"", "\"modelId\":\"other\",\"palette\"")));
  CHECK_ERR(Error::ModelMismatch, parse(swap(full(), "\"modelId\":\"nl-51-v1\",\"configurationDigest\"", "\"modelId\":\"nl-51-v1x\",\"configurationDigest\"")));
  CHECK_ERR(Error::ModelMismatch, parse(swap(full(), "\"modelId\":\"nl-51-v1\",\"configurationDigest\"", "\"modelId\":\"" + std::string(200, 'm') + "\",\"configurationDigest\"")));
  CHECK_ERR(Error::BadDigest, parse(swap(full(), DIGEST, "0123")));
  CHECK_ERR(Error::BadDigest, parse(swap(full(), DIGEST, "0123456789ABCDEF0123456789abcdef0123456789abcdef0123456789abcdef")));
  CHECK_ERR(Error::MissingField, parse(swap(full(), "\"inputGeneration\":1700000000123,", "")));
  CHECK_ERR(Error::MissingField, parse(swap(full(), "\"modelId\":\"nl-51-v1\",\"configurationDigest\"", "\"configurationDigest\"")));
  CHECK_ERR(Error::MissingField, parse(swap(full(), ",\"brightness\":255", "")));
  CHECK_ERR(Error::MissingField, parse(swap(full(), "\"palette\":[0,255,65280,16776960,16744448,16711680],", "")));
  CHECK_ERR(Error::DuplicateKey, parse(swap(full(), "\"serverTime\"", "\"inputGeneration\":1,\"serverTime\"")));
  CHECK_ERR(Error::DuplicateKey, parse(swap(full(), ",\"brightness\":255", ",\"brightness\":255,\"brightness\":255")));

  const char* bad[] = {
      "{", "}", "[]", "null", "{\"contractVersion\":1", "{\"contractVersion\":1,}",
      "{\"contractVersion\" 1}", "{contractVersion:1}", "{\"contractVersion\":tru}",
      "{\"contractVersion\":1}x", "{\"contractVersion\":1}{}", "{\"a\":\"unterminated}",
      "{\"a\":\"bad\\q\"}", "{\"a\":[1,]}", "{\"a\":01}", "{\"a\":-}", "{\"a\":+1}",
      "{\"contractVersion\":\"1\"}", "{\"contractVersion\":true}",
  };
  for (size_t i = 0; i < sizeof(bad) / sizeof(bad[0]); i++) {
    Error e = parseEnvelope(bad[i], strlen(bad[i]), MODEL, meta, def, inputs);
    checks++;
    if (e == Error::Ok) {
      failures++;
      printf("FAIL: malformed accepted: %s\n", bad[i]);
    }
  }
  CHECK_ERR(Error::Malformed, parse("{\"contractVersion\":1}x"));
  CHECK_ERR(Error::Malformed, parse(swap(full(), "\"serverTime\":\"", "\"serverTime\":\"\x01")));
  CHECK_ERR(Error::NonInteger, parse(swap(full(), "\"brightness\":255", "\"brightness\":255.0")));
  CHECK_ERR(Error::NonInteger, parse(swap(full(), "\"brightness\":255", "\"brightness\":2.55e2")));
  CHECK_ERR(Error::NonInteger, parse(swap(full(), "\"inputGeneration\":1700000000123", "\"inputGeneration\":1e3")));
  // Truncating a valid body anywhere never crashes and never validates.
  std::string f = full();
  for (size_t n = 0; n < f.size(); n++) {
    Error e = parseEnvelope(f.c_str(), n, MODEL, meta, def, inputs);
    checks++;
    if (e == Error::Ok) {
      failures++;
      printf("FAIL: truncated body of %zu bytes accepted\n", n);
    }
  }
}

static void testRangesOverflow() {
  CHECK_ERR(Error::ZeroDuration, parse(swap(full(), "\"durationMs\":1750,\"from\":0", "\"durationMs\":0,\"from\":0")));
  CHECK_ERR(Error::ZeroDuration, parse(swap(full(), "\"durationMs\":1750,\"from\":0", "\"durationMs\":-5,\"from\":0")));
  CHECK_ERR(Error::ZeroDuration, parse(swap(full(), "\"periodMs\":5000", "\"periodMs\":0")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"durationMs\":1750,\"from\":0", "\"durationMs\":86400001,\"from\":0")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"periodMs\":5000", "\"periodMs\":86400001")));
  CHECK_ERR(Error::Overflow, parse(swap(full(), "\"durationMs\":1750,\"from\":0", "\"durationMs\":2147483648,\"from\":0")));
  CHECK_ERR(Error::Overflow, parse(swap(full(), "\"durationMs\":1750,\"from\":0", "\"durationMs\":99999999999999999999,\"from\":0")));
  CHECK_ERR(Error::Overflow, parse(swap(full(), "\"inputGeneration\":1700000000123", "\"inputGeneration\":9223372036854775808")));
  CHECK_ERR(Error::Ok, parse(swap(full(), "\"inputGeneration\":1700000000123", "\"inputGeneration\":9223372036854775807")));
  // A track total above one day overflows even when every segment is legal.
  std::string two = "\"segments\":[{\"durationMs\":86400000,\"from\":0,\"to\":1},{\"durationMs\":1,\"from\":1,\"to\":2}]";
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"segments\":[{\"durationMs\":1750,\"from\":0,\"to\":50},{\"durationMs\":1750,\"from\":50,\"to\":0},{\"durationMs\":1500,\"from\":0,\"to\":0}]", two)));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"from\":0,\"to\":50", "\"from\":0,\"to\":1000001")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"from\":0,\"to\":50", "\"from\":-1,\"to\":50")));
  CHECK_ERR(Error::Ok, parse(swap(full(), "\"from\":0,\"to\":50", "\"from\":0,\"to\":1000000")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"brightness\":255", "\"brightness\":256")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"brightness\":255", "\"brightness\":-1")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "[0,255,65280", "[0,255,16777216")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "[0,255,65280", "[0,-1,65280")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"offsetMs\":0", "\"offsetMs\":5000")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"close\":3500", "\"close\":0")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"close\":3500", "\"close\":86400001")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"open\":0,\"close\":3500", "\"open\":-1,\"close\":3500")));
  CHECK_ERR(Error::OutOfRange, parse(swap(full(), "\"generation\":1700000000123", "\"generation\":-1")));
}

// Values from the Java formula (RenderContract.cosine/linear) evaluated with double precision.
static int32_t javaCosine(int32_t from, int32_t to, int32_t d, int32_t t) {
  if (t <= 0) return from;
  if (t >= d) return to;
  double w = (1 - cos(M_PI * t / d)) / 2;
  return (int32_t)floor(from + (to - from) * w + 0.5);
}
static int32_t javaLinear(int32_t from, int32_t to, int32_t d, int32_t t) {
  long long c = t < 0 ? 0 : (t > d ? d : t);
  long long delta = (long long)to - from;
  long long num = 2 * delta * c + d, den = 2LL * d;
  long long q = num / den;
  if ((num % den != 0) && ((num < 0) != (den < 0))) q--;
  return (int32_t)(from + q);
}

static void testValues() {
  CHECK_ERR(Error::Ok, parse(full()));
  const Track& near = def.tracks[2];
  const Track& far = def.tracks[3];
  // Expected values computed with Java's formula (see report): near fade peaks at 50.
  CHECK(trackValueAt(def, near, 0) == 0);
  CHECK(trackValueAt(def, near, 1) == 0);
  CHECK(trackValueAt(def, near, 875) == 25);
  CHECK(trackValueAt(def, near, 1749) == 50);
  CHECK(trackValueAt(def, near, 1750) == 50);
  CHECK(trackValueAt(def, near, 2625) == 25);
  CHECK(trackValueAt(def, near, 3499) == 0);
  CHECK(trackValueAt(def, near, 3500) == 0);
  CHECK(trackValueAt(def, near, 4999) == 0);
  CHECK(trackValueAt(def, near, 5000) == 0);   // after the end: last "to"
  CHECK(trackValueAt(def, near, -7) == 0);     // before 0: first "from"
  CHECK(trackValueAt(def, far, 500) == 15);
  CHECK(trackValueAt(def, far, 1000) == 30);
  CHECK(trackValueAt(def, far, 1500) == 15);
  CHECK(trackValueAt(def, far, 2000) == 0);
  CHECK(trackValueAt(def, def.tracks[1], 123456) == 80);
  CHECK(trackValueAt(def, def.tracks[0], 123456) == 0);
  // Half-open gates: near fade window [0, 3500).
  CHECK(gateOpen(def.gates[0].open, def.gates[0].close, 0));
  CHECK(gateOpen(def.gates[0].open, def.gates[0].close, 3499));
  CHECK(!gateOpen(def.gates[0].open, def.gates[0].close, 3500));
  CHECK(!gateOpen(def.gates[0].open, def.gates[0].close, -1));
  // Linear matches Java exactly, including negative deltas and half-up ties.
  CHECK(linearValue(0, 100, 1000, 500) == 50);
  CHECK(linearValue(0, 1, 2, 1) == 1);     // 0.5 rounds up
  CHECK(linearValue(1, 0, 2, 1) == 1);     // 1 + floor(-0.5 + 0.5)... Java: 1 + floorDiv(-2+2,4)=1
  CHECK(linearValue(10, 0, 4, 1) == 8);    // 7.5 -> 8
  CHECK(linearValue(10, 0, 4, 99) == 0 && linearValue(10, 0, 4, -3) == 10);
  int mismatches = 0, maxDiff = 0, samples = 0;
  // Linear: exhaustive-ish comparison with the Java rules.
  for (int d = 1; d <= 40; d++)
    for (int from = 0; from <= 12; from++)
      for (int to = 0; to <= 12; to++)
        for (int t = -2; t <= d + 2; t++) CHECK(linearValue(from, to, d, t) == javaLinear(from, to, d, t));
  // Cosine tolerance: equal to the double formula except within ~1e-7 of a rounding tie.
  const int32_t deltas[][2] = {{0, 50}, {50, 0}, {0, 30}, {30, 0}, {0, 100}, {100, 0}, {0, 255},
                               {7, 1000000}, {1000000, 0}, {3, 999999}};
  const int32_t durations[] = {2, 3, 7, 1000, 1750, 1749, 2000, 2500, 86400000 / 1000};
  for (size_t a = 0; a < sizeof(deltas) / sizeof(deltas[0]); a++)
    for (size_t b = 0; b < sizeof(durations) / sizeof(durations[0]); b++)
      for (int32_t t = -1; t <= durations[b] + 1; t += (durations[b] > 5000 ? 7 : 1)) {
        int32_t got = cosineValue(deltas[a][0], deltas[a][1], durations[b], t);
        int32_t want = javaCosine(deltas[a][0], deltas[a][1], durations[b], t);
        int diff = abs(got - want);
        samples++;
        if (diff) mismatches++;
        if (diff > maxDiff) maxDiff = diff;
      }
  printf("cosine vs Java double: %d samples, %d mismatches, max diff %d\n", samples, mismatches, maxDiff);
  CHECK(maxDiff <= 1);
  CHECK(mismatches * 200 <= samples);  // 0.5 percent at most, only for deltas near 1e6
  // Deltas up to 255 (every real profile): any difference from Java must sit on an exact real
  // rounding tie (for example t/d = 1/2 or 1/3), where Java's own result is floating-point noise.
  int tieOnly = 0, offTie = 0;
  for (int32_t delta = 1; delta <= 255; delta += 2)
    for (int32_t d = 2; d <= 600; d += 23)
      for (int32_t t = 1; t < d; t++) {
        double w = (1 - cos(M_PI * t / d)) / 2;
        double ex = delta * w + 0.5;
        double tieDistance = fabs(ex - floor(ex + 0.5));
        int32_t j = javaCosine(0, delta, d, t);
        int32_t g = cosineValue(0, delta, d, t);
        if (g != j) (tieDistance < 1e-6 ? tieOnly : offTie)++;
        // Descending ramps (from > to) round the same way.
        int32_t jd = javaCosine(delta, 0, d, t);
        int32_t gd = cosineValue(delta, 0, d, t);
        if (gd != jd) (tieDistance < 1e-6 ? tieOnly : offTie)++;
      }
  printf("cosine small-delta differences: %d on exact ties, %d elsewhere\n", tieOnly, offTie);
  CHECK(offTie == 0);
  // The default profile (deltas up to 100, durations 1000/1750) matches exactly everywhere.
  for (int32_t t = 0; t <= 1750; t++) {
    CHECK(cosineValue(0, 50, 1750, t) == javaCosine(0, 50, 1750, t));
    CHECK(cosineValue(50, 0, 1750, t) == javaCosine(50, 0, 1750, t));
  }
  for (int32_t t = 0; t <= 1000; t++) {
    CHECK(cosineValue(0, 30, 1000, t) == javaCosine(0, 30, 1000, t));
    CHECK(cosineValue(30, 0, 1000, t) == javaCosine(30, 0, 1000, t));
  }
  CHECK(cosineValue(5, 9, 100, 0) == 5 && cosineValue(5, 9, 100, 100) == 9);
}

static Rgb px[MAX_PIXELS];
static Engine engine;

static void stageOk(const std::string& s) {
  CHECK_ERR(Error::Ok, engine.stage(s.c_str(), s.size(), MODEL));
  CHECK(engine.activate() == Activation::Activated);
}

static void testEngine() {
  CHECK(!engine.hasActive());
  engine.setCeiling(255);
  engine.render(0, px, MAX_PIXELS);
  for (size_t i = 0; i < MAX_PIXELS; i++) CHECK(px[i].r == 0 && px[i].g == 0 && px[i].b == 0);
  CHECK(engine.activate() == Activation::Nothing);

  stageOk(full());
  CHECK(engine.hasActive());
  CHECK(std::string(engine.activeDigest()) == DIGEST);
  CHECK(engine.activeGeneration() == 1700000000123LL);
  CHECK(engine.effectiveBrightness() == 255);

  engine.render(875, px, MAX_PIXELS);
  CHECK(px[0].r == 0 && px[0].g == 0 && px[0].b == 0);
  CHECK(px[1].r == 0 && px[1].g == 204 && px[1].b == 0);   // solid 80 percent of 255
  CHECK(px[2].g == 64);                                    // near fade value 25: 255*.25=63.75
  CHECK(px[3].r == 74 && px[3].g == 0);                    // far value 29 (red): 255*.29=73.95
  CHECK(px[51].r == 204 && px[51].g == 102 && px[51].b == 0);  // 80 percent orange #FF8000
  CHECK(px[4].r == 0 && px[4].g == 0 && px[4].b == 0);         // unbound pixel off
  engine.render(1000, px, MAX_PIXELS);
  CHECK(px[3].r == 77);                                    // far peak 30: 76.5 -> 77
  engine.render(1750, px, MAX_PIXELS);
  CHECK(px[2].g == 128);                                   // near peak 50: 127.5 -> 128
  CHECK(px[3].r == 10);                                    // far value 4
  // Shared clock: near and far restart each 5000 ms; dark in the rest of the cycle.
  engine.render(3500, px, MAX_PIXELS);
  CHECK(px[2].g == 0 && px[3].r == 0);
  engine.render(5000 + 875, px, MAX_PIXELS);
  CHECK(px[2].g == 64 && px[3].r == 74);
  // uint32 wrap keeps the phase: elapsed 4294970875 ms is 875 ms into a 5000 ms cycle.
  engine.render(4294967000u, px, MAX_PIXELS);
  engine.render(3579u, px, MAX_PIXELS);
  CHECK(px[1].g == 204 && px[2].g == 64);

  // Ceiling clamp: only lowers.
  engine.setCeiling(100);
  CHECK(engine.effectiveBrightness() == 100);
  engine.render(875, px, MAX_PIXELS);
  CHECK(px[1].g == 80);
  engine.setCeiling(0);
  engine.render(875, px, MAX_PIXELS);
  CHECK(px[1].g == 0 && px[51].r == 0);
  engine.setCeiling(255);
  // Server brightness below the ceiling wins; above it never raises the ceiling.
  stageOk(envelope(swap(DEFINITION, "\"brightness\":255", "\"brightness\":10"), ""));
  CHECK(engine.effectiveBrightness() == 10);
  engine.setCeiling(5);
  CHECK(engine.effectiveBrightness() == 5);
  engine.setCeiling(255);
  stageOk(envelope(DEFINITION, ""));
  CHECK(engine.effectiveBrightness() == 255);
  engine.setCeiling(40);
  CHECK(engine.effectiveBrightness() == 40);
  engine.setCeiling(255);
}

static void testNoPartialActivation() {
  Engine e;
  e.setCeiling(255);
  std::string good = full();
  CHECK_ERR(Error::Ok, e.stage(good.c_str(), good.size(), MODEL));
  CHECK(e.activate() == Activation::Activated);
  e.render(875, px, MAX_PIXELS);
  Rgb before[MAX_PIXELS];
  for (size_t i = 0; i < MAX_PIXELS; i++) before[i] = px[i];
  std::string digest = e.activeDigest();

  std::string newDef = swap(DEFINITION, "\"from\":80,\"to\":80", "\"from\":40,\"to\":40");
  std::string badOnes[] = {
      "{\"contractVersion\":1,",
      swap(envelope(newDef, INPUTS), "\"modelId\":\"nl-51-v1\",\"configurationDigest\"", "\"modelId\":\"x\",\"configurationDigest\""),
      envelope(swap(newDef, "\"brightness\":255", "\"brightness\":999"), INPUTS),
      envelope(newDef, swap(INPUTS, "\"trackRef\":3", "\"trackRef\":77")),
      envelope(newDef, manyBindings(53)),
      swap(envelope(newDef, INPUTS), "\"contractVersion\":1,\"modelId\":\"nl-51-v1\",\"conf", "\"contractVersion\":3,\"modelId\":\"nl-51-v1\",\"conf"),
  };
  for (size_t i = 0; i < sizeof(badOnes) / sizeof(badOnes[0]); i++) {
    CHECK(e.stage(badOnes[i].c_str(), badOnes[i].size(), MODEL) != Error::Ok);
    CHECK(e.activate() == Activation::Nothing);
    e.render(875, px, MAX_PIXELS);
    for (size_t k = 0; k < MAX_PIXELS; k++)
      CHECK(px[k].r == before[k].r && px[k].g == before[k].g && px[k].b == before[k].b);
    CHECK(digest == e.activeDigest());
  }
  // A failed stage also drops an earlier pending update (superseded).
  std::string pending = envelope(newDef, INPUTS);
  CHECK_ERR(Error::Ok, e.stage(pending.c_str(), pending.size(), MODEL));
  CHECK(e.stage("{", 1, MODEL) == Error::Malformed);
  CHECK(e.activate() == Activation::Nothing);

  // Inputs-only update validated against the active definition at activation.
  std::string badIn = envelope("", swap(INPUTS, "\"trackRef\":3", "\"trackRef\":4"));
  CHECK_ERR(Error::Ok, e.stage(badIn.c_str(), badIn.size(), MODEL));
  Error reason = Error::Ok;
  CHECK(e.activate(&reason) == Activation::Rejected && reason == Error::BadReference);
  e.render(875, px, MAX_PIXELS);
  for (size_t k = 0; k < MAX_PIXELS; k++) CHECK(px[k].g == before[k].g && px[k].r == before[k].r);
  // New definition shrinking the track list while old inputs stay: rejected, active kept.
  std::string shrink = envelope(manyTracks(1, 1), "");
  CHECK_ERR(Error::Ok, e.stage(shrink.c_str(), shrink.size(), MODEL));
  CHECK(e.activate(&reason) == Activation::Rejected && reason == Error::BadReference);
  e.render(875, px, MAX_PIXELS);
  for (size_t k = 0; k < MAX_PIXELS; k++) CHECK(px[k].g == before[k].g && px[k].r == before[k].r);
  // Good inputs-only update: swaps inputs, keeps definition and clock.
  std::string moved = envelope("", "{\"generation\":9,\"bindings\":[{\"pixel\":7,\"trackRef\":1,\"paletteRef\":3}]}");
  CHECK_ERR(Error::Ok, e.stage(moved.c_str(), moved.size(), MODEL));
  CHECK(e.activate() == Activation::Activated);
  CHECK(e.activeGeneration() == 9);
  e.render(875, px, MAX_PIXELS);
  CHECK(px[7].r == 204 && px[7].g == 204 && px[7].b == 0 && px[1].g == 0);
  // Digest of an inputs-only update is carried along.
  CHECK(digest == e.activeDigest());

  // Inputs with no definition ever: rejected.
  Engine fresh;
  std::string inOnly = envelope("", INPUTS);
  CHECK_ERR(Error::Ok, fresh.stage(inOnly.c_str(), inOnly.size(), MODEL));
  CHECK(fresh.activate(&reason) == Activation::Rejected && reason == Error::NoDefinition);
  CHECK(!fresh.hasActive());
  // Definition only, no inputs yet: stays dark but definition active.
  std::string defOnly = envelope(DEFINITION, "");
  CHECK_ERR(Error::Ok, fresh.stage(defOnly.c_str(), defOnly.size(), MODEL));
  CHECK(fresh.activate() == Activation::Activated);
  CHECK(!fresh.hasActive());
  fresh.render(0, px, MAX_PIXELS);
  CHECK(px[1].g == 0);
}

static void testSizes() {
  printf("sizeof(Definition)=%zu sizeof(Inputs)=%zu sizeof(Engine)=%zu\n", sizeof(Definition),
         sizeof(Inputs), sizeof(Engine));
  CHECK(sizeof(Engine) < 24 * 1024);
}
