int main() {
  testValid();
  testBounds();
  testReferences();
  testVersionModelMalformed();
  testRangesOverflow();
  testValues();
  testEngine();
  testNoPartialActivation();
  testSizes();
  printf("%d checks, %d failures\n", checks, failures);
  return failures ? 1 : 0;
}
